export declare const tmpl = "\n<style>\n:host {\n  display: block;\n  position: relative;\n  touch-action: pan-y;\n  aspect-ratio: var(--_ar, auto);\n}\n:host([hidden]) {\n  display: none;\n}\n\n.frame {\n  --_p: 50%;\n  position: relative;\n  display: grid;\n  grid-template-columns: minmax(0, 1fr);\n  height: 100%;\n  overflow: hidden;\n  border-radius: var(--ba-radius, 0);\n  background: var(--ba-background, transparent);\n  isolation: isolate;\n}\n\n.pane {\n  grid-area: 1 / 1;\n  position: relative;\n  min-width: 0;\n  overflow: hidden;\n}\n\n.pane.before {\n  clip-path: inset(0 calc(100% - var(--_p)) 0 0);\n}\n:host([orientation=\"vertical\"]) .pane.before {\n  clip-path: inset(0 0 calc(100% - var(--_p)) 0);\n}\n\nimg.auto,\n::slotted(img),\n::slotted(video),\n::slotted(canvas),\n::slotted(svg) {\n  display: block;\n  width: 100%;\n  height: 100%;\n  object-fit: var(--ba-object-fit, cover);\n  user-select: none;\n  -webkit-user-drag: none;\n}\nimg[hidden] {\n  display: none;\n}\n\n.label {\n  position: absolute;\n  top: 0;\n  margin: .6rem;\n  padding: .2em .6em;\n  border-radius: 2px;\n  background: var(--ba-label-bg, rgb(0 0 0 / .55));\n  color: var(--ba-label-color, #fff);\n  font: 500 11px/1.6 var(--ba-label-font, ui-monospace, SFMono-Regular, Menlo, monospace);\n  letter-spacing: .08em;\n  text-transform: uppercase;\n  white-space: nowrap;\n  backdrop-filter: blur(3px);\n  pointer-events: none;\n}\n.label.before {\n  left: 0;\n}\n.label.after {\n  right: 0;\n}\n:host([orientation=\"vertical\"]) .label.after {\n  top: auto;\n  bottom: 0;\n  right: 0;\n}\n.label[hidden] {\n  display: none;\n}\n\n.rail {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  left: var(--_p);\n  width: max(var(--ba-handle-size, 44px), 44px);\n  transform: translateX(-50%);\n  display: grid;\n  place-items: center;\n  cursor: col-resize;\n  touch-action: none;\n}\n:host([orientation=\"vertical\"]) .rail {\n  top: var(--_p);\n  bottom: auto;\n  left: 0;\n  right: 0;\n  width: auto;\n  height: max(var(--ba-handle-size, 44px), 44px);\n  transform: translateY(-50%);\n  cursor: row-resize;\n}\n:host([disabled]) .rail {\n  cursor: default;\n}\n\n.line {\n  position: absolute;\n  top: 0;\n  bottom: 0;\n  left: 50%;\n  width: var(--ba-divider-width, 2px);\n  transform: translateX(-50%);\n  background: var(--ba-divider-color, #fff);\n  box-shadow: 0 0 0 1px rgb(0 0 0 / .16);\n}\n:host([orientation=\"vertical\"]) .line {\n  top: 50%;\n  bottom: auto;\n  left: 0;\n  right: 0;\n  width: auto;\n  height: var(--ba-divider-width, 2px);\n  transform: translateY(-50%);\n}\n\n.handle {\n  position: relative;\n  width: var(--ba-handle-size, 44px);\n  height: var(--ba-handle-size, 44px);\n  padding: 0;\n  border: 0;\n  border-radius: 50%;\n  background: var(--ba-handle-bg, #fff);\n  color: var(--ba-handle-color, #111);\n  box-shadow: 0 1px 3px rgb(0 0 0 / .3), 0 0 0 1px rgb(0 0 0 / .08);\n  display: grid;\n  place-items: center;\n  cursor: inherit;\n  touch-action: none;\n}\n.handle svg {\n  width: 60%;\n  height: 60%;\n  display: block;\n}\n:host([orientation=\"vertical\"]) .handle svg {\n  transform: rotate(90deg);\n}\n\n.handle:focus-visible {\n  outline: 2px solid var(--ba-focus-ring, #0aa);\n  outline-offset: 3px;\n}\n\n/* Focus taken by a drag is not focus the user asked to see. */\n.handle.by-pointer:focus-visible {\n  outline: none;\n}\n\n:host([disabled]) .handle {\n  opacity: .45;\n}\n\n.frame:not(.is-dragging) .pane.before {\n  transition: clip-path .18s ease;\n}\n.frame:not(.is-dragging) .rail {\n  transition: left .18s ease, top .18s ease;\n}\n\n/* Selectors must match the rules above exactly: :not(.is-dragging) adds a\n   class to their specificity, and a shorter override here would lose. */\n@media (prefers-reduced-motion: reduce) {\n  .frame:not(.is-dragging) .pane.before,\n  .frame:not(.is-dragging) .rail {\n    transition: none;\n  }\n}\n</style>\n<div class=\"frame\" part=\"frame\">\n  <div class=\"pane after\" part=\"pane after\">\n    <img class=\"auto after\" part=\"image\" hidden alt=\"\">\n    <slot name=\"after\"></slot>\n    <span class=\"label after\" part=\"label\" hidden></span>\n  </div>\n  <div class=\"pane before\" part=\"pane before\">\n    <img class=\"auto before\" part=\"image\" hidden alt=\"\">\n    <slot name=\"before\"></slot>\n    <span class=\"label before\" part=\"label\" hidden></span>\n  </div>\n  <div class=\"rail\">\n    <span class=\"line\" part=\"divider\"></span>\n    <button class=\"handle\" part=\"handle\" type=\"button\" role=\"slider\"\n      aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"50\"></button>\n  </div>\n</div>";
